<script setup lang="ts">
const {state,change,undo,reset,canUndo,saveError}=usePuzzleState('wunder')
function set(i:number,value:string) { const counts=state.value.counts.slice(); counts[i]=value===''?null:Number(value); change({counts}) }
</script>
<template><div class="puzzle"><p>Count the lights beneath the balcony in Tyr’s head. Keep the two sequences separate.</p><div v-for="sequence in 2" :key="sequence"><strong>Sequence {{ sequence }}</strong><div class="p-grid"><label v-for="(name,i) in ['Left blinks → Amplitude','Right blinks → Frequency']" :key="name">{{ name }}<select :value="state.counts[(sequence-1)*2+i] ?? ''" @change="set((sequence-1)*2+i,($event.target as HTMLSelectElement).value)"><option value="">Count blinks</option><option v-for="n in (i===0?7:8)" :key="n" :value="n">{{ n }}</option></select></label></div></div><div class="p-result" aria-live="polite"><div v-for="sequence in 2" :key="sequence"><strong>{{ sequence }}.</strong> Amplitude <b>{{ state.counts[(sequence-1)*2] || '—' }}</b> · Frequency <b>{{ state.counts[(sequence-1)*2+1] || '—' }}</b></div></div><PuzzleActions :can-undo="canUndo" :save-error="saveError" @undo="undo" @reset="reset" /></div></template>
